const { useState } = React;

function App() {
  const [page, setPage] = useState("details");
  const [form, setForm] = useState({
    username: "",
    email: "",
    dob: "",
    city: "",
  });
  const [errors, setErrors] = useState({});

  const cities = ["New York", "London", "Paris", "Tokyo", "Sydney"];

  function validate() {
    const newErrors = {};
    if (!form.username.trim()) newErrors.username = "Username is required";
    if (!form.email.trim()) newErrors.email = "Email is required";
    else if (!/^\S+@\S+\.\S+$/.test(form.email)) newErrors.email = "Email is invalid";
    if (!form.dob) newErrors.dob = "Date of birth is required";
    if (!form.city) newErrors.city = "City is required";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  function handleNext() {
    if (validate()) {
      setPage("address");
    }
  }

  function handleBack() {
    // For step 1, Back could just reset or do nothing
    // We'll just reset form for demo
    setForm({ username: "", email: "", dob: "", city: "" });
    setErrors({});
  }

  if (page === "address") {
    return (
      <main style={styles.container}>
        <h2 style={styles.heading}>Address page</h2>
        <p>This is the next step after Your details.</p>
        <button style={styles.button} onClick={() => setPage("details")}>Back to Your details</button>
      </main>
    );
  }

  return (
    <main style={styles.container}>
      <p style={styles.stepText}>Step 1 of 2</p>
      <h1 style={styles.heading}>Your details</h1>
      <form
        onSubmit={e => {
          e.preventDefault();
          handleNext();
        }}
        noValidate
        aria-label="Step 1 registration form"
        style={styles.form}
      >
        <label style={styles.label} htmlFor="username">
          Username
          <input
            id="username"
            name="username"
            type="text"
            value={form.username}
            onChange={e => setForm({ ...form, username: e.target.value })}
            style={styles.input}
            aria-describedby={errors.username ? "username-error" : undefined}
            aria-invalid={errors.username ? "true" : "false"}
          />
          {errors.username && (
            <p id="username-error" role="alert" style={styles.error}>
              {errors.username}
            </p>
          )}
        </label>

        <label style={styles.label} htmlFor="email">
          Email
          <input
            id="email"
            name="email"
            type="email"
            value={form.email}
            onChange={e => setForm({ ...form, email: e.target.value })}
            style={styles.input}
            aria-describedby={errors.email ? "email-error" : undefined}
            aria-invalid={errors.email ? "true" : "false"}
          />
          {errors.email && (
            <p id="email-error" role="alert" style={styles.error}>
              {errors.email}
            </p>
          )}
        </label>

        <label style={styles.label} htmlFor="dob">
          Date of birth
          <input
            id="dob"
            name="dob"
            type="date"
            value={form.dob}
            onChange={e => setForm({ ...form, dob: e.target.value })}
            style={styles.input}
            aria-describedby={errors.dob ? "dob-error" : undefined}
            aria-invalid={errors.dob ? "true" : "false"}
          />
          {errors.dob && (
            <p id="dob-error" role="alert" style={styles.error}>
              {errors.dob}
            </p>
          )}
        </label>

        <label style={styles.label} htmlFor="city">
          City
          <select
            id="city"
            name="city"
            value={form.city}
            onChange={e => setForm({ ...form, city: e.target.value })}
            style={styles.input}
            aria-describedby={errors.city ? "city-error" : undefined}
            aria-invalid={errors.city ? "true" : "false"}
          >
            <option value="">Select a city</option>
            {cities.map(city => (
              <option key={city} value={city}>
                {city}
              </option>
            ))}
          </select>
          {errors.city && (
            <p id="city-error" role="alert" style={styles.error}>
              {errors.city}
            </p>
          )}
        </label>

        <div style={styles.buttonRow}>
          <button type="button" onClick={handleBack} style={styles.button}>
            Back
          </button>
          <button type="submit" style={styles.button}>
            Next
          </button>
        </div>
      </form>
    </main>
  );
}

const styles = {
  container: {
    maxWidth: 360,
    margin: "2rem auto",
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    color: "#1a237e",
    padding: "0 1rem",
  },
  stepText: {
    fontSize: "0.9rem",
    marginBottom: "0.25rem",
    fontWeight: "500",
  },
  heading: {
    fontSize: "1.8rem",
    marginBottom: "1rem",
    fontWeight: "600",
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "1rem",
  },
  label: {
    display: "flex",
    flexDirection: "column",
    fontSize: "1rem",
    fontWeight: "500",
  },
  input: {
    marginTop: "0.25rem",
    padding: "0.5rem",
    fontSize: "1rem",
    borderRadius: "4px",
    border: "2px solid #1a237e",
    fontFamily: "inherit",
  },
  buttonRow: {
    display: "flex",
    justifyContent: "space-between",
    marginTop: "1rem",
  },
  button: {
    backgroundColor: "#1a237e",
    color: "white",
    border: "none",
    borderRadius: "6px",
    padding: "0.5rem 1.5rem",
    fontSize: "1rem",
    cursor: "pointer",
    fontWeight: "600",
    minWidth: 100,
  },
  error: {
    color: "#d32f2f",
    fontSize: "0.85rem",
    marginTop: "0.25rem",
  },
};

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

